sp_widget.client_script:
function widgetController($scope, spModal, spUtil, $document) {
	var c = this;

	// 1. Create the keydown handler function
	function handleKeyPress(event) {
		// Check if the user pressed 'm' or 'M'
		if (event.key === 'q' || event.key === 'Q') {
			triggerPortalNotification();
		}
	}

	// 2. Attach the listener using Angular's $document
	$document.on('keydown', handleKeyPress);

	// 3. CRUCIAL: Clean up the listener when the widget destroys/reloads
	// This completely prevents multiple popups from stacking!
	$scope.$on('$destroy', function() {
		$document.off('keydown', handleKeyPress);
	});

	function triggerPortalNotification() {
		spModal.open({
			title: '⚠️ URGENT MEDICATION REMINDER',
			message: 'You need to give the scheduled medicine to Patient: John Doe right now. Did the patient take the medicine?',
			buttons: [
				{label: '❌ Not Taken', cancel: true}, 
				{label: '✅ Taken', primary: true}     
			]
		}).then(function() {
			// Path A: User clicks "Taken"
			spUtil.addInfoMessage("Dose marked as 'Taken'. Tracking log updated successfully.");
		}, function() {
			// Path B: User clicks "Not Taken"
			var notes = prompt("⚠️ REASON REQUIRED:\nPlease enter the notes/reason why the medicine was not taken:");

			if (!notes || notes.trim() === "") {
				alert("Notes are mandatory. Action aborted.");
				triggerPortalNotification(); 
			} else {
				spUtil.addErrorMessage("Dose marked as 'Not-taken'. Notes recorded: \"" + notes + "\". Alert sent to Guardian.");
			}
		});
	}
}
